(function(root) {
    'use strict';

    function GridStack(el, opts) {
        this.el = el;
        this.opts = Object.assign({
            column: 12,
            cellHeight: 80,
            margin: 8,
            float: false,
            animate: true,
            disableResize: false,
            disableDrag: false
        }, opts || {});
        this._items = [];
        this._callbacks = {};
        this.el.classList.add('grid-stack', 'gs-12');
        this.el.style.position = 'relative';
    }

    GridStack.init = function(opts, elOrSelector) {
        var el = typeof elOrSelector === 'string'
            ? document.querySelector(elOrSelector)
            : (elOrSelector || document.querySelector('.grid-stack'));
        if (!el) return null;
        return new GridStack(el, opts);
    };

    var proto = GridStack.prototype;

    proto.addWidget = function(widgetOpts) {
        var item = document.createElement('div');
        item.className = 'grid-stack-item';
        item.setAttribute('gs-x', widgetOpts.x || 0);
        item.setAttribute('gs-y', widgetOpts.y || 0);
        item.setAttribute('gs-w', widgetOpts.w || 4);
        item.setAttribute('gs-h', widgetOpts.h || 3);
        item.setAttribute('gs-id', widgetOpts.id || '');

        var content = document.createElement('div');
        content.className = 'grid-stack-item-content';
        if (widgetOpts.content) content.innerHTML = widgetOpts.content;
        if (widgetOpts.el) content.appendChild(widgetOpts.el);
        item.appendChild(content);

        var ch = this.opts.cellHeight;
        var mg = this.opts.margin;
        var cols = this.opts.column;
        var x = parseInt(widgetOpts.x) || 0;
        var y = parseInt(widgetOpts.y) || 0;
        var w = parseInt(widgetOpts.w) || 4;
        var h = parseInt(widgetOpts.h) || 3;

        item.style.position = 'absolute';
        item.style.left = (x / cols * 100) + '%';
        item.style.top = (y * (ch + mg)) + 'px';
        item.style.width = (w / cols * 100) + '%';
        item.style.height = (h * ch + (h - 1) * mg) + 'px';
        item.style.padding = (mg / 2) + 'px';
        item.style.boxSizing = 'border-box';

        this.el.appendChild(item);
        this._items.push({ el: item, x: x, y: y, w: w, h: h, id: widgetOpts.id });

        this._updateContainerHeight();
        this._enableDrag(item);
        return item;
    };

    proto.removeWidget = function(el, removeDOM) {
        if (removeDOM !== false && el.parentNode) el.parentNode.removeChild(el);
        this._items = this._items.filter(function(i) { return i.el !== el; });
        this._updateContainerHeight();
    };

    proto.removeAll = function(removeDOM) {
        var self = this;
        this._items.slice().forEach(function(item) {
            self.removeWidget(item.el, removeDOM !== false);
        });
    };

    proto.getGridItems = function() {
        return this._items.map(function(i) {
            return {
                el: i.el,
                x: parseInt(i.el.getAttribute('gs-x')) || 0,
                y: parseInt(i.el.getAttribute('gs-y')) || 0,
                w: parseInt(i.el.getAttribute('gs-w')) || 4,
                h: parseInt(i.el.getAttribute('gs-h')) || 3,
                id: i.el.getAttribute('gs-id') || ''
            };
        });
    };

    proto.on = function(event, callback) {
        if (!this._callbacks[event]) this._callbacks[event] = [];
        this._callbacks[event].push(callback);
        return this;
    };

    proto._emit = function(event, data) {
        (this._callbacks[event] || []).forEach(function(cb) { cb(data); });
    };

    proto._updateContainerHeight = function() {
        var maxBottom = 0;
        var ch = this.opts.cellHeight;
        var mg = this.opts.margin;
        this._items.forEach(function(item) {
            var y = parseInt(item.el.getAttribute('gs-y')) || 0;
            var h = parseInt(item.el.getAttribute('gs-h')) || 3;
            var bottom = (y + h) * (ch + mg);
            if (bottom > maxBottom) maxBottom = bottom;
        });
        this.el.style.minHeight = (maxBottom + mg) + 'px';
    };

    proto._enableDrag = function(item) {
        var self = this;
        var contentEl = item.querySelector('.grid-stack-item-content');
        if (!contentEl || self.opts.disableDrag) return;

        contentEl.style.cursor = 'move';
        var startX, startY, origLeft, origTop;

        contentEl.addEventListener('mousedown', function(e) {
            if (e.target.closest('.dropdown, .btn, a, input, select')) return;
            e.preventDefault();
            startX = e.clientX;
            startY = e.clientY;
            origLeft = item.offsetLeft;
            origTop = item.offsetTop;
            item.classList.add('ui-draggable-dragging');

            function onMove(ev) {
                var dx = ev.clientX - startX;
                var dy = ev.clientY - startY;
                item.style.left = (origLeft + dx) + 'px';
                item.style.top = (origTop + dy) + 'px';
            }

            function onUp() {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
                item.classList.remove('ui-draggable-dragging');

                var cols = self.opts.column;
                var ch = self.opts.cellHeight;
                var mg = self.opts.margin;
                var containerW = self.el.offsetWidth;

                var newX = Math.round(item.offsetLeft / containerW * cols);
                var newY = Math.round(item.offsetTop / (ch + mg));
                newX = Math.max(0, Math.min(cols - parseInt(item.getAttribute('gs-w')), newX));
                newY = Math.max(0, newY);

                item.setAttribute('gs-x', newX);
                item.setAttribute('gs-y', newY);
                item.style.left = (newX / cols * 100) + '%';
                item.style.top = (newY * (ch + mg)) + 'px';

                self._updateContainerHeight();
                self._emit('change', self.getGridItems());
            }

            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
        });
    };

    proto.compact = function() {};
    proto.disable = function() { this.opts.disableDrag = true; this.opts.disableResize = true; };
    proto.enable = function() { this.opts.disableDrag = false; this.opts.disableResize = false; };
    proto.destroy = function(removeDOM) { if (removeDOM) this.removeAll(); };

    root.GridStack = GridStack;
    if (typeof module !== 'undefined' && module.exports) module.exports = GridStack;
})(typeof window !== 'undefined' ? window : this);
